const getRecommendations = async (userId) => {
  return User.aggregate([
    // 1. Match the specific user efficiently using an index
    { $match: { _id: mongoose.Types.ObjectId(userId) } },
    // 2. Join with the 'songs' collection
    {
      $lookup: {
        from: "songs",
        localField: "recommendedTracks", // Array of song IDs
        foreignField: "_id",
        as: "trackDetails"
      }
    },
    // 3. Deconstruct the array for processing
    { $unwind: "$trackDetails" },
    // 4. Shape the output document (Projection)
    {
      $project: {
        _id: 0,
        trackId: "$trackDetails._id",
        title: "$trackDetails.title",
        // ... other fields
      }
    },
    // 5. Sort and limit the results
    { $sort: { score: -1 } },
    { $limit: 20 }
  ]);
};
